/// One size of a procedural gate brick.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GateVariant {
    /// Procedural half-extent `[x, y, z]` (the brick's `size`) that selects this variant.
    pub half_size: [i32; 3],
    /// Physical (on-brick) wire ports at this size, in brick order. The component's
    /// other ports still exist and are reachable through the omniport.
    pub ports: &'static [&'static str],
}

/// A gate brick asset (`PB_Gate_*`) placed as a procedural brick at one of a fixed
/// list of sizes; the game rejects any other size for it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ProceduralGate {
    /// Procedural brick asset name, e.g. "PB_Gate_QueueTicks".
    pub asset: &'static str,
    /// Component type the brick carries, e.g. "BrickComponentType_QueueTicks".
    pub component: &'static str,
    /// Size variants, smallest first.
    pub variants: &'static [GateVariant],
}

impl ProceduralGate {
    /// The variant placed at `half_size`, if it is one of this gate's valid sizes.
    pub fn variant(&self, half_size: [i32; 3]) -> Option<&'static GateVariant> {
        let variants: &'static [GateVariant] = self.variants;
        variants.iter().find(|v| v.half_size == half_size)
    }

    /// The smallest variant that physically exposes every port in `ports`.
    pub fn smallest_with_ports(&self, ports: &[&str]) -> Option<&'static GateVariant> {
        let variants: &'static [GateVariant] = self.variants;
        variants
            .iter()
            .find(|v| ports.iter().all(|p| v.ports.contains(p)))
    }
}

