/// A procedural gate by brick asset name.
pub fn procedural_gate(asset: &str) -> Option<&'static ProceduralGate> {
    PROCEDURAL_GATES
        .binary_search_by(|g| g.asset.cmp(asset))
        .ok()
        .map(|i| &PROCEDURAL_GATES[i])
}

/// The procedural gate brick that carries `component`, if any.
pub fn procedural_gate_for_component(component: &str) -> Option<&'static ProceduralGate> {
    PROCEDURAL_GATES.iter().find(|g| g.component == component)
}
